sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }
	//alert(newValue);
	var dt = newValue.toString().split(':')[0];
	//alert(dt);
	if(dt>24){
		g_form.clearValue("emp_work_start");
		g_form.showErrorBox("emp_work_start","Work hours should be in Military time (from 0 to 24 hr) ",true);
	 }

   //Type appropriate comment here, and begin script below

}
